import {mount} from 'cypress/react';
import {Harness,stubRpc,site} from '../support/harness';
const button=(label:string)=>cy.get(`[role="button"][aria-label="${label}"]`);
const uploadId='12345678-1234-4123-8123-123456789012';
const file={id:'1',filename:'example.txt',size:5,mimeType:'text/plain',author:'Example user',created:'2026-11-03T10:00:00Z'};
for(const transport of ['rest','twg'] as const){
function open(){mount(<Harness transport={transport} twgWrites/>);cy.get('[aria-label^="Open details for TEST-1:"]').click();}
function select(){
 // The real picker uses a detached input; attach it for Cypress without opening an OS dialog.
 cy.window().then(win=>cy.stub(win.HTMLInputElement.prototype,'click').callsFake(function(this:HTMLInputElement){if(this.type!=='file')throw Error('Unexpected input click');win.document.body.appendChild(this);}));
 button('Add attachment').click();cy.get('input[type=file]').selectFile({contents:Cypress.Buffer.from('hello'),fileName:'example.txt',mimeType:'text/plain'},{force:true});
}
describe(`Mocked ${transport} attachment workflows`,()=>{
 beforeEach(()=>{cy.viewport(1200,800);stubRpc();});
 it('upload a selected file → send bytes and refresh attachment list',()=>{
  let uploaded=false;
  cy.intercept('POST','/__rpc/attachments.list',req=>req.reply({site,files:uploaded?[file]:[]}));
  cy.intercept('POST','/__rpc/attachments.begin',req=>{expect(req.body).to.deep.equal({key:'TEST-1',filename:'example.txt',size:5,mimeType:'text/plain'});req.reply({uploadId});}).as('begin');
  cy.intercept('POST','/__rpc/attachments.chunk',req=>{expect(req.body).to.deep.equal({uploadId,offset:0,base64:'aGVsbG8='});req.reply({received:5});}).as('chunk');
  cy.intercept('POST','/__rpc/attachments.finish',req=>{expect(req.body).to.deep.equal({uploadId});uploaded=true;req.reply([file]);}).as('finish');
  open();select();button('Upload').click();cy.wait(['@begin','@chunk','@finish']);cy.contains('Attachment uploaded.').should('be.visible');cy.contains('example.txt').should('be.visible');button('Download attachment').should('be.visible');button('Upload').should('not.exist');
 });
 it('chunk fails → cancel incomplete transfer and keep selected file for retry',()=>{
  cy.intercept('POST','/__rpc/attachments.begin',{body:{uploadId}});
  cy.intercept('POST','/__rpc/attachments.chunk',{statusCode:500,body:{error:'Chunk rejected'}});
  cy.intercept('POST','/__rpc/attachments.cancel',req=>{expect(req.body.uploadId).to.equal(uploadId);req.reply({cancelled:true});}).as('cancel');
  open();select();button('Upload').click();cy.wait('@cancel');cy.contains('Chunk rejected').should('be.visible');button('Upload').should('not.have.attr','aria-disabled','true');button('Cancel').click();button('Add attachment').should('be.visible');
 });
 it('image preview → render authenticated mock bytes without external navigation',()=>{
  const png='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aX1sAAAAASUVORK5CYII=';
  const image={...file,filename:'example.png',mimeType:'image/png',size:65};
  cy.intercept('POST','/__rpc/attachments.list',{body:{site,files:[image]}});
  cy.intercept('POST','/__rpc/attachments.read',req=>{expect(req.body).to.deep.equal({key:'TEST-1',id:'1',offset:0});req.reply({base64:png,total:65,mimeType:'image/png'});}).as('read');
  open();button('Preview image').click();cy.wait('@read');cy.get('[aria-label="example.png"]').should('be.visible');button('Close preview').click();cy.get('[aria-label="example.png"]').should('not.exist');
 });
});

}
